<?php

namespace App\Models\Concerns;

use App\Enums\TaskType;
use App\Models\Task;
use Illuminate\Database\Eloquent\Relations\MorphMany;

/**
 * "Call them back Thursday" style tasks attached to a CRM record (Guest,
 * Deal) - ordinary Task rows pointing at it through Task's own `source`
 * morph, tagged TaskType::CrmFollowUp so they stay separate from tasks
 * generated by forms/checklists/bookings.
 */
trait HasFollowUpTasks
{
    public function followUpTasks(): MorphMany
    {
        return $this->morphMany(Task::class, 'source')->where('task_type', TaskType::CrmFollowUp);
    }
}
